// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using Campground.Shared.Network;

namespace Campground.Shared.Injection
{
    /// <summary>
    /// Pure HTML editing for index.html, generalised from Bonfire's WebInjection: idempotent, base-URL aware,
    /// and replacing stale copies in place instead of adding a second one.
    /// </summary>
    internal static class IndexHtml
    {
        internal const string RuntimeId = "campground-runtime";

        // The base URL goes inside src="...". It is an admin setting, but a quote or a "<" in it would end the
        // attribute and put markup into every page, so it is HTML-encoded (1.0.1, issue #61).
        private static string BaseAttr(string? baseUrl) => System.Net.WebUtility.HtmlEncode(JellyfinNetworkSettings.NormalizeBaseUrl(baseUrl));

        /// <summary>The body tag for one registration.</summary>
        internal static string BodyTag(ScriptRegistration reg, string? baseUrl)
            => $"<script src=\"{BaseAttr(baseUrl)}{reg.Path}?v={Uri.EscapeDataString(reg.Version)}\" defer></script>";

        /// <summary>The inline runtime tag.</summary>
        internal static string RuntimeTag(string version, string script)
            => $"<script id=\"{RuntimeId}\" data-v=\"{version}\">{script.Replace("</script", "<\\/script", StringComparison.OrdinalIgnoreCase)}</script>";

        /// <summary>
        /// Adds or updates every fragment. Returns true when the document changed. Never throws on odd
        /// documents: without &lt;head&gt; or &lt;/body&gt; the matching fragments are skipped.
        /// </summary>
        internal static bool Apply(
            string html,
            string? baseUrl,
            IReadOnlyList<ScriptRegistration> tags,
            (string Version, string Script)? runtime,
            out string result)
            => Apply(html, baseUrl, tags, runtime, RuntimeTag, out result);

        private static bool Apply(
            string html,
            string? baseUrl,
            IReadOnlyList<ScriptRegistration> tags,
            (string Version, string Script)? runtime,
            Func<string, string, string> runtimeTag,
            out string result)
        {
            var original = html;
            var nl = html.Contains("\r\n", StringComparison.Ordinal) ? "\r\n" : "\n";

            // 1. Runtime first in <head>, so every plugin script can rely on window.Campground.
            if (runtime is { } rt)
            {
                html = UpsertHead(html, RuntimeId, runtimeTag(rt.Version, rt.Script), nl, prepend: true);
            }

            // 2. Head snippets.
            foreach (var t in tags)
            {
                if (!string.IsNullOrEmpty(t.HeadSnippet) && !string.IsNullOrEmpty(t.HeadId))
                {
                    html = UpsertHead(html, t.HeadId!, t.HeadSnippet!, nl, prepend: false);
                }
            }

            // 3. Body scripts, in order, before </body>.
            foreach (var t in tags)
            {
                var tag = BodyTag(t, baseUrl);
                var existing = BodyRegex(t.Path);
                if (existing.IsMatch(html))
                {
                    if (!html.Contains(tag, StringComparison.Ordinal))
                    {
                        // MatchEvaluator, not a replacement string: "$" would be a substitution token.
                        html = existing.Replace(html, _ => tag, 1);
                    }
                }
                else
                {
                    var idx = html.LastIndexOf("</body>", StringComparison.OrdinalIgnoreCase);
                    if (idx != -1)
                    {
                        html = html.Insert(idx, tag + nl);
                    }
                }
            }

            result = html;
            return !string.Equals(original, html, StringComparison.Ordinal);
        }

        /// <summary>
        /// Same as <see cref="Apply(string, string?, IReadOnlyList{ScriptRegistration}, ValueTuple{string, string}?, out string)"/>,
        /// but with <paramref name="asFiles"/> the runtime and every head snippet go in as
        /// <c>&lt;script src&gt;</c> tags the middleware answers (0.10.0, issue #20 M1). A Content-Security-Policy
        /// of <c>script-src 'self'</c> drops inline scripts without a word, and with them every plugin's start-up.
        /// The tags keep their ids, so an older owner's inline form and this one replace each other in place.
        /// </summary>
        internal static bool Apply(
            string html,
            string? baseUrl,
            IReadOnlyList<ScriptRegistration> tags,
            (string Version, string Script)? runtime,
            bool asFiles,
            out string result)
        {
            if (!asFiles)
            {
                return Apply(html, baseUrl, tags, runtime, out result);
            }

            var files = new List<ScriptRegistration>(tags.Count);
            foreach (var t in tags)
            {
                var body = HeadScriptBody(t);
                files.Add(body == null ? t : t with { HeadSnippet = HeadFileTag(t.HeadId!, body, baseUrl) });
            }

            return Apply(html, baseUrl, files, runtime, (version, _) => RuntimeFileTag(version, baseUrl), out result);
        }

        /// <summary>Where the runtime is served, after the base URL.</summary>
        internal const string RuntimePath = "/Campground/runtime.js";

        /// <summary>Where head snippets are served, after the base URL: <c>/Campground/head/&lt;HeadId&gt;.js</c>.</summary>
        internal const string HeadPathPrefix = "/Campground/head/";

        /// <summary>The runtime as a file. No defer: it must run before the head snippets and plugin scripts.</summary>
        internal static string RuntimeFileTag(string version, string? baseUrl)
            => $"<script id=\"{RuntimeId}\" data-v=\"{version}\" src=\"{BaseAttr(baseUrl)}{RuntimePath}?v={Uri.EscapeDataString(version)}\"></script>";

        /// <summary>
        /// The code inside a head snippet, when the snippet is exactly one plain inline
        /// <c>&lt;script id="HeadId"&gt;</c> and so can be served as a file. Null otherwise (it then stays inline).
        /// </summary>
        internal static string? HeadScriptBody(ScriptRegistration reg)
        {
            if (string.IsNullOrEmpty(reg.HeadSnippet) || string.IsNullOrEmpty(reg.HeadId))
            {
                return null;
            }

            var m = Regex.Match(
                reg.HeadSnippet!,
                "^\\s*<script\\s+id=\"" + Regex.Escape(reg.HeadId!) + "\"\\s*>([\\s\\S]*?)</script>\\s*$",
                RegexOptions.IgnoreCase);
            if (!m.Success || m.Groups[1].Value.IndexOf("</script", StringComparison.OrdinalIgnoreCase) != -1)
            {
                return null;
            }

            return m.Groups[1].Value;
        }

        /// <summary>A short content hash for a head file's cache-buster.</summary>
        internal static string ContentVersion(string body)
            => Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(body)), 0, 6).ToLowerInvariant();

        private static string HeadFileTag(string headId, string body, string? baseUrl)
            => $"<script id=\"{headId}\" src=\"{BaseAttr(baseUrl)}{HeadPathPrefix}{Uri.EscapeDataString(headId)}.js?v={ContentVersion(body)}\"></script>";

        /// <summary>
        /// True when the document has somewhere to put fragments: a &lt;head&gt; or a &lt;/body&gt;. Tells
        /// "nothing to do" apart from "nowhere to do it" when <c>Apply</c> returns false.
        /// </summary>
        internal static bool HasAnchors(string html)
            => Regex.IsMatch(html, "<head[^>]*>", RegexOptions.IgnoreCase)
               || html.IndexOf("</body>", StringComparison.OrdinalIgnoreCase) != -1;

        /// <summary>
        /// True when every fragment is present and current (nothing to do). Pass <paramref name="asFiles"/> to ask
        /// about the form the middleware serves.
        /// </summary>
        internal static bool IsCurrent(string html, string? baseUrl, IReadOnlyList<ScriptRegistration> tags, (string Version, string Script)? runtime, bool asFiles = false)
            => !Apply(html, baseUrl, tags, runtime, asFiles, out _);

        /// <summary>Removes every fragment for the given registrations (and the runtime).</summary>
        internal static bool Remove(string html, IReadOnlyList<ScriptRegistration> tags, out string result)
        {
            var original = html;
            html = HeadRegex(RuntimeId, removal: true).Replace(html, string.Empty);
            foreach (var t in tags)
            {
                if (!string.IsNullOrEmpty(t.HeadId))
                {
                    html = HeadRegex(t.HeadId!, removal: true).Replace(html, string.Empty);
                }

                html = BodyRegex(t.Path, removal: true).Replace(html, string.Empty);
            }

            result = html;
            return !string.Equals(original, html, StringComparison.Ordinal);
        }

        private static string UpsertHead(string html, string id, string fragment, string nl, bool prepend)
        {
            var re = HeadRegex(id);
            if (re.IsMatch(html))
            {
                return html.Contains(fragment, StringComparison.Ordinal) ? html : re.Replace(html, _ => fragment, 1);
            }

            var head = Regex.Match(html, "<head[^>]*>", RegexOptions.IgnoreCase);
            if (!head.Success)
            {
                return html;
            }

            if (prepend)
            {
                return html.Insert(head.Index + head.Length, nl + fragment);
            }

            var close = html.IndexOf("</head>", StringComparison.OrdinalIgnoreCase);
            return close == -1 ? html.Insert(head.Index + head.Length, nl + fragment) : html.Insert(close, fragment + nl);
        }

        private static Regex HeadRegex(string id, bool removal = false)
            => new(
                (removal ? @"(\r?\n)?" : string.Empty) + "<script id=\"" + Regex.Escape(id) + "\"[^>]*>[\\s\\S]*?</script>" + (removal ? @"(\r?\n)?" : string.Empty),
                RegexOptions.IgnoreCase);

        private static Regex BodyRegex(string path, bool removal = false)
            => new(
                "<script[^>]*src=[\"'][^\"']*" + Regex.Escape(path) + "[^\"']*[\"'][^>]*>\\s*(</script>)?" + (removal ? @"(\r?\n)?" : string.Empty),
                RegexOptions.IgnoreCase);
    }
}
